function i(t,n={}){return t?new Intl.DateTimeFormat("en-GB",{day:"2-digit",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit",...n}).format(new Date(t)):"—"}function o(t){if(!t)return"—";const n=Date.now()-new Date(t).getTime(),e=Math.floor(n/6e4);if(e<1)return"just now";if(e<60)return`${e}m ago`;const r=Math.floor(e/60);return r<24?`${r}h ago`:`${Math.floor(r/24)}d ago`}function a(t,n=40){return t?t.length>n?t.slice(0,n)+"…":t:"—"}function u(t=""){return t.split(" ").map(n=>n[0]).join("").toUpperCase().slice(0,2)}export{o as a,i as f,u as i,a as t};
